def maxLen(n, edges, label):
    from functools import lru_cache
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    @lru_cache(maxsize=None)
    def extend(u, v, mask):
        # palindromic path runs from u to v using the nodes in mask;
        # return the maximum number of extra nodes that can be added around it
        best = 0
        for a in adj[u]:
            if (mask >> a) & 1:
                continue
            for b in adj[v]:
                if a == b or (mask >> b) & 1 or label[a] != label[b]:
                    continue
                nxt = mask | (1 << a) | (1 << b)
                lo, hi = (a, b) if a < b else (b, a)
                best = max(best, 2 + extend(lo, hi, nxt))
        return best

    ans = 1
    for i in range(n):
        ans = max(ans, 1 + extend(i, i, 1 << i))
    for u, v in edges:
        if label[u] == label[v]:
            lo, hi = (u, v) if u < v else (v, u)
            ans = max(ans, 2 + extend(lo, hi, (1 << u) | (1 << v)))
    return ans
